head.script:
scwin.init = function() {
    var jsonData = [{
            "label": "input",
            "code": "input"
        },
        {
            "label": "calendar",
            "code": "calendar"
        },
        {
            "label": "checkbox",
            "code": "checkbox"
        },
        {
            "label": "select",
            "code": "select"
        },
        {
            "label": "textarea",
            "code": "textarea"
        },
        {
            "label": "radio",
            "code": "radio"
        }
    ];
    dlt_select.setJSON(jsonData);
    var sel_sampleData = [{
            "col1": "축구",
            "col2": "1"
        },
        {
            "col1": "농구",
            "col2": "2"
        },
        {
            "col1": "야구",
            "col2": "3"
        },
        {
            "col1": "배구",
            "col2": "4"
        }
    ];
    sel_sample.setJSON(sel_sampleData);
    var arr = [];
    for (var i = 0; i < 5; i++) {
        arr.push({
            co1: "input",
            col2: "bb",
            col3: "cc"
        });
    }
    dataList1.setJSON(arr);
};
scwin.grd_onviewchange = function(info) {
    var inputType = info.newValue;
    var obj = scwin.inputTypeCustomObj[inputType];
    grd.setCellInputType(info.rowIndex, "col2", obj);
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
    scwin.simulateWrapper('#G_grd__dynamic_textarea_0_1', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grd_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grd___selectbox_col1_itemTable_4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grd_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('G_'+$p.id+'grd__dynamic_textarea_0_1').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.inputTypeCustomObj = {
        calendar: {
            inputType: "calendar"
        },
        radio: {
            inputType: "radio"
        },
        checkbox: {
            inputType: "checkbox"
        },
        input: {
            inputType: "input"
        },
        textarea: {
            inputType: "textarea"
        },
        select: {
            inputType: "select",
            options: {
                viewType: "default"
            },
            itemSet: {
                nodeset: "data:sel_sample",
                label: "col1",
                value: "col2"
            }
        }
    };
    //값 변경 시 col2의 inputType을 동적으로 변경한다.
    scwin.init();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
